import {TOOL_CALL, scriptedProvider, registryReturning} from './chatOrchestratorTestSupport.js';

const SENT_AT = '2026-01-01T00:00:00.000Z';

function createSession(content: string): ChatSession {
  return {
    sessionId: 's1',
    userId: 'u1',
    entries: [{role: 'user', content, timestamp: SENT_AT}],
  };
}

const promptBuilder = new PromptBuilder({identity: 'You are a test assistant.'});

function captureUsage(): {hooks: OrchestratorHooks; getResult: () => UsageMetadata | undefined} {
  let captured: UsageMetadata | undefined;
  return {
    hooks: {
      afterModelResponse: async (_session, _text, usage) => {
        captured = usage;
      },
    },
    getResult: () => captured,
  };
}

function makeToolOrchestrator(rounds: MessageChunk[][], hooks: OrchestratorHooks) {
  return createChatOrchestrator(scriptedProvider(rounds), promptBuilder, registryReturning(), {hooks});
}

async function runRounds(rounds: MessageChunk[][]): Promise<UsageMetadata | undefined> {
  const {hooks, getResult} = captureUsage();
  const orchestrator = makeToolOrchestrator(rounds, hooks);
  await orchestrator.processMessage(createSession('ask'));
  return getResult();
}

describe('ChatOrchestrator usage accumulation across tool rounds (acceptance)', () => {
  it('accumulates usage across two tool rounds and reports the sum to afterModelResponse', async () => {
    const round1Usage: UsageMetadata = {inputTokens: 10, outputTokens: 5, totalTokens: 15};
    const round2Usage: UsageMetadata = {inputTokens: 15, outputTokens: 8, totalTokens: 23};
    const usage = await runRounds([
      [TOOL_CALL, {type: 'stop', stopReason: 'tool_use', usage: round1Usage}],
      [{type: 'text', text: 'answer'}, {type: 'stop', stopReason: 'end_turn', usage: round2Usage}],
    ]);
    expect(usage).toEqual({inputTokens: 25, outputTokens: 13, totalTokens: 38});
  });

  it('reports usage from a single round (no tool calls) without modification, preserving backward compatibility', async () => {
    const usage: UsageMetadata = {inputTokens: 10, outputTokens: 5, totalTokens: 15};
    const {hooks, getResult} = captureUsage();
    const orchestrator = createChatOrchestrator(
      scriptedProvider([
        [
          {type: 'text', text: 'answer without tools'},
          {type: 'stop', stopReason: 'end_turn', usage},
        ],
      ]),
      promptBuilder,
      undefined,
      {hooks}
    );
    await orchestrator.processMessage(createSession('ask'));
    expect(getResult()).toEqual(usage);
  });

  it('handles a round with no usage followed by a round with usage', async () => {
    const round2Usage: UsageMetadata = {inputTokens: 20, outputTokens: 10, totalTokens: 30};
    const usage = await runRounds([
      [TOOL_CALL, {type: 'stop', stopReason: 'tool_use'}],
      [{type: 'text', text: 'done'}, {type: 'stop', stopReason: 'end_turn', usage: round2Usage}],
    ]);
    expect(usage).toEqual(round2Usage);
  });

  it('handles a round with usage followed by a round with no usage', async () => {
    const round1Usage: UsageMetadata = {inputTokens: 15, outputTokens: 8, totalTokens: 23};
    const usage = await runRounds([
      [TOOL_CALL, {type: 'stop', stopReason: 'tool_use', usage: round1Usage}],
      [{type: 'text', text: 'done'}, {type: 'stop', stopReason: 'end_turn'}],
    ]);
    expect(usage).toEqual(round1Usage);
  });

  it('handles three tool rounds accumulating usage across all of them', async () => {
    const round1Usage: UsageMetadata = {inputTokens: 10, outputTokens: 5, totalTokens: 15};
    const round2Usage: UsageMetadata = {inputTokens: 12, outputTokens: 4, totalTokens: 16};
    const round3Usage: UsageMetadata = {inputTokens: 8, outputTokens: 3, totalTokens: 11};
    const usage = await runRounds([
      [TOOL_CALL, {type: 'stop', stopReason: 'tool_use', usage: round1Usage}],
      [TOOL_CALL, {type: 'stop', stopReason: 'tool_use', usage: round2Usage}],
      [{type: 'text', text: 'final answer'}, {type: 'stop', stopReason: 'end_turn', usage: round3Usage}],
    ]);
    expect(usage).toEqual({inputTokens: 30, outputTokens: 12, totalTokens: 42});
  });

  it('does not report undefined or NaN when some rounds report no usage', async () => {
    const round1Usage: UsageMetadata = {inputTokens: 10, outputTokens: 5, totalTokens: 15};
    const usage = await runRounds([
      [TOOL_CALL, {type: 'stop', stopReason: 'tool_use', usage: round1Usage}],
      [TOOL_CALL, {type: 'stop', stopReason: 'tool_use'}],
      [{type: 'text', text: 'final'}, {type: 'stop', stopReason: 'end_turn'}],
    ]);
    expect(usage).toEqual(round1Usage);
  });

  it('handles zero usage across all rounds', async () => {
    const usage = await runRounds([
      [TOOL_CALL, {type: 'stop', stopReason: 'tool_use'}],
      [{type: 'text', text: 'done'}, {type: 'stop', stopReason: 'end_turn'}],
    ]);
    expect(usage).toBeUndefined();
  });

  it('accumulates usage with partial zero rounds in the middle', async () => {
    const round1Usage: UsageMetadata = {inputTokens: 5, outputTokens: 2, totalTokens: 7};
    const round3Usage: UsageMetadata = {inputTokens: 8, outputTokens: 3, totalTokens: 11};
    const usage = await runRounds([
      [TOOL_CALL, {type: 'stop', stopReason: 'tool_use', usage: round1Usage}],
      [TOOL_CALL, {type: 'stop', stopReason: 'tool_use'}],
      [{type: 'text', text: 'final'}, {type: 'stop', stopReason: 'end_turn', usage: round3Usage}],
    ]);
    expect(usage).toEqual({inputTokens: 13, outputTokens: 5, totalTokens: 18});
  });
});

